            for (int playerHero = 0;
                 playerHero < recipient.m_numHeroes;
                 ++playerHero) {
                hero* target = g_game->getHero(
                    recipient.m_heroes[playerHero]);
                if (target->giveArtifact(&artifact, 0, 0))
                    break;
            }
